def binary_gap(n):
    s = bin(n)[2:]
    best = 0
    cur = 0
    in_ones = False
    for ch in s:
        if ch == '0':
            if in_ones:
                cur += 1
        else:
            if in_ones:
                best = max(best, cur)
            cur = 0
            in_ones = True
    return best
```

